if(isset($_POST['Submit'])){$mid=filter_input(INPUT_POST,'mid',FILTER_VALIDATE_INT);$name=trim($_POST['name']??'');$gender=$_POST['gender']??'';$dob=$_POST['dob']??'';$contact=trim($_POST['contact']??'');$address=trim($_POST['address']??'');$username=trim($_POST['username']??'');$password=$_POST['pwd']??'';$region=trim($_POST['region']??'');if(!$mid||$mid<1||!$name||!in_array($gender,['female','male'],true)||!$dob||!$contact||!$address||!$username||strlen($password)<6||!$region){$message='Alanları kontrol edin. Şifre en az 6 karakter olmalıdır.';$type='error';}else{$q=$conn->prepare('SELECT MID FROM manager WHERE MID=? OR Username=? LIMIT 1');$q->bind_param('is',$mid,$username);$q->execute();$exists=$q->get_result()->fetch_assoc();$q->close();if($exists){$message='MID veya kullanıcı adı zaten kullanılıyor.';$type='error';}else{$hash=password_hash($password,PASSWORD_DEFAULT);$q=$conn->prepare('INSERT INTO manager (MID,Name,Gender,DOB,Contact,Address,Username,Password,region) VALUES (?,?,?,?,?,?,?,?,?)');$q->bind_param('issssssss',$mid,$name,$gender,$dob,$contact,$address,$username,$hash,$region);if($q->execute()){$message='Manager başarıyla kaydedildi.';$type='success';}else{$message='Kayıt sırasında hata oluştu.';$type='error';}$q->close();}}}
